#!/usr/bin/env bash
set -Eeuo pipefail

# ============================================================
# C01 CNN — ONE METHOD ONLY
# Method: dt1d
# Scientific protocol is unchanged; only scheduling is split.
# ============================================================
SESSION_START_EPOCH="$(date +%s)"
METHOD="dt1d"
TASK_ID="C01_${METHOD}"
REPO_URL="${DT1D_CNN_REPO_URL:-https://github.com/tydeptrai21042004/whc-dt1d.git}"
REPO_COMMIT="fda0047228b3cf048ebb43d93f3970574fbef9ef"
WORKDIR=/kaggle/working
REPO_DIR="$WORKDIR/whc-dt1d-$TASK_ID"
DATA_ROOT="$WORKDIR/data_C01_CNN"
PROGRESS_ROOT="$WORKDIR/progress_$TASK_ID"
RESULT_ZIP="$WORKDIR/${TASK_ID}_results.zip"
SAFE_MINUTES=690
RESERVE_MINUTES=30
SAFETY_FACTOR=1.55
export SESSION_START_EPOCH METHOD TASK_ID REPO_DIR DATA_ROOT PROGRESS_ROOT RESULT_ZIP SAFE_MINUTES RESERVE_MINUTES SAFETY_FACTOR

pack_results() {
  python - <<'PYZIP'
import os, zipfile
from pathlib import Path
r=Path(os.environ['PROGRESS_ROOT'])
d=Path(os.environ['RESULT_ZIP'])
d.unlink(missing_ok=True)
with zipfile.ZipFile(d,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
    if r.exists():
        for p in r.rglob('*'):
            if p.is_file() and p.suffix.lower() not in {'.pth','.pt','.ckpt'}:
                z.write(p,p.relative_to(r.parent))
print('RESULT_ZIP=',d)
PYZIP
  ls -lh "$RESULT_ZIP" || true
}
trap 'rc=$?; trap - EXIT; pack_results || true; exit $rc' EXIT

# Clone exactly the same commit as the successful C01 run.
rm -rf "$REPO_DIR"
for n in 1 2 3; do
  git clone --filter=blob:none --no-checkout "$REPO_URL" "$REPO_DIR" && break || sleep $((n*5))
done
[[ -d "$REPO_DIR/.git" ]] || { echo "ERROR: clone failed"; exit 2; }
cd "$REPO_DIR"
git fetch --depth 1 origin "$REPO_COMMIT"
git checkout --detach "$REPO_COMMIT"
ACTUAL_COMMIT="$(git rev-parse HEAD)"
[[ "$ACTUAL_COMMIT" == "$REPO_COMMIT" ]] || { echo "ERROR: commit mismatch"; exit 3; }
echo "SOURCE_COMMIT=$ACTUAL_COMMIT"

python -m pip install -q --upgrade-strategy only-if-needed -r requirements-kaggle.txt

# Write audited helper sources into /kaggle/working.
python - <<'PYTOOLS'
import base64
from pathlib import Path
Path('/kaggle/working/cnn_method_task.py').write_bytes(base64.b64decode(''))
Path('/kaggle/working/apply_unified_configs.py').write_bytes(base64.b64decode(''))
PYTOOLS
python -m py_compile /kaggle/working/cnn_method_task.py /kaggle/working/apply_unified_configs.py

# Start from an empty working progress folder, then restore ONLY this method.
rm -rf "$PROGRESS_ROOT"
mkdir -p "$PROGRESS_ROOT"
python - <<'PYRESTORE'
import os, shutil, zipfile
from pathlib import Path
method=os.environ['METHOD']
task=os.environ['TASK_ID']
dst=Path(os.environ['PROGRESS_ROOT'])
inp=Path('/kaggle/input')
restored=False

def newest(pattern):
    xs=list(inp.rglob(pattern)) if inp.exists() else []
    return max(xs,key=lambda p:p.stat().st_mtime) if xs else None

def extract(z):
    tmp=Path('/kaggle/working')/('_restore_'+task)
    shutil.rmtree(tmp,ignore_errors=True)
    tmp.mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(z) as f:
        bad=f.testzip()
        if bad:
            raise RuntimeError(f'Corrupt ZIP {z}: {bad}')
        f.extractall(tmp)
    return tmp

# Preferred: previous result ZIP for this exact method.
z=newest(f'{task}_results*.zip')
if z:
    tmp=extract(z)
    roots=list(tmp.rglob(f'progress_{task}'))
    if len(roots)==1:
        shutil.rmtree(dst,ignore_errors=True)
        shutil.move(str(roots[0]),str(dst))
        restored=True
        print('RESTORED_METHOD',method,z)
    shutil.rmtree(tmp,ignore_errors=True)

# Migration path: import ONLY this method from the old packed C01 ZIP.
if not restored:
    z=newest('PACK_C01_CNN_results*.zip')
    if z:
        tmp=extract(z)
        packs=list(tmp.rglob('packed_progress_PACK_C01_CNN'))
        candidates=[p/method for p in packs if (p/method/'TASK_SPEC.json').is_file()]
        if len(candidates)==1:
            shutil.rmtree(dst,ignore_errors=True)
            shutil.copytree(candidates[0],dst)
            restored=True
            print('IMPORTED_OLD_PACK_METHOD',method,z)
        shutil.rmtree(tmp,ignore_errors=True)

print('RESTORE_STATUS', 'resumed' if restored else 'fresh', method)
PYRESTORE

mkdir -p "$DATA_ROOT" "$PROGRESS_ROOT"
cp /kaggle/working/cnn_method_task.py "$PROGRESS_ROOT/_runner_source.py"
cp /kaggle/working/apply_unified_configs.py "$PROGRESS_ROOT/_config_patch_source.py"

python - <<'PYGPU'
import torch
assert torch.cuda.is_available(),'Enable Kaggle GPU accelerator.'
print('GPU count=',torch.cuda.device_count())
for i in range(torch.cuda.device_count()):
    print(i,torch.cuda.get_device_name(i))
PYGPU

CONFIG_PATH="$REPO_DIR/configs/experiments/table_03.yaml"
python /kaggle/working/apply_unified_configs.py --family cnn "$CONFIG_PATH"

echo "============================================================"
echo "RUNNING ONLY METHOD: $METHOD"
echo "Output: $RESULT_ZIP"
echo "If incomplete, upload that ZIP to the next Kaggle session"
echo "and rerun THIS SAME method cell."
echo "============================================================"

set +e
python /kaggle/working/cnn_method_task.py   --repo-root "$REPO_DIR"   --config "$CONFIG_PATH"   --method "$METHOD"   --data-path "$DATA_ROOT"   --progress-root "$PROGRESS_ROOT"   --safe-minutes "$SAFE_MINUTES"   --session-start-epoch "$SESSION_START_EPOCH"   --safety-factor "$SAFETY_FACTOR"   --reserve-minutes "$RESERVE_MINUTES"   --max-gpus 2
RC=$?
set -e

pack_results
trap - EXIT

python - <<'PYSTATUS'
import json, os
from pathlib import Path
p=Path(os.environ['PROGRESS_ROOT'])/'TASK_STATUS.json'
if p.is_file():
    d=json.loads(p.read_text())
    print('
FINAL_METHOD_STATUS')
    print(json.dumps(d,indent=2))
    if d.get('complete'):
        print('
METHOD_COMPLETE: yes')
    else:
        print('
METHOD_COMPLETE: no')
        print('NEXT_STEP: add the produced method ZIP as Kaggle input and rerun the SAME method cell.')
else:
    print('WARNING: TASK_STATUS.json was not produced; inspect the log above.')
PYSTATUS

exit "$RC"
